<?php $recruiter=$currentUser['role']==='Rekruter';$heading=$recruiter?'Profil & Dokumen Pendaftar':'Detail Lamaran';$kicker='LAMARAN #'.str_pad((string)$lamaran['idLamaran'],5,'0',STR_PAD_LEFT);$subtitle=$lamaran['namaLowongan'].' · '.$lamaran['namaPerusahaan'];require ROOT.'/app/Views/components/heading.php';$item=$lamaran;?>
<section class="card"><div class="section-heading"><h2>Status seleksi</h2><?= badge($lamaran['statusLamaran']) ?></div><?php if($lamaran['statusLamaran']!=='Draf'):require ROOT.'/app/Views/components/timeline.php';endif;?><?php if($lamaran['lowonganDihapus']||$lamaran['perusahaanDihapus']):?><div class="alert info">Lowongan/perusahaan tidak lagi tersedia. Data lamaran berikut adalah riwayat yang tetap disimpan.</div><?php endif;?></section>
<div class="content-with-aside"><div class="stack"><section class="card"><div class="section-heading"><h2>Data Mahasiswa</h2><span class="badge blue"><?= e($lamaran['NIM']) ?></span></div><div class="profile-banner"><span class="avatar large"><?= e(initials($lamaran['namaMahasiswa'])) ?></span><div><h2><?= e($lamaran['namaMahasiswa']) ?></h2><p><?= e($lamaran['jurusan']) ?> · Semester <?= e($lamaran['semester']) ?></p></div></div><dl class="summary-list two-up"><div><dt>Email</dt><dd><?= e($lamaran['email']) ?></dd></div><div><dt>Telepon</dt><dd><?= e($lamaran['telepon']) ?></dd></div><div><dt>IPK</dt><dd><?= e($lamaran['IPK']) ?></dd></div><div><dt>Dikirim pada</dt><dd><?= tanggal($lamaran['tanggalMelamar'],'d M Y, H:i') ?> WIB</dd></div></dl></section><section class="card"><h2>Dokumen Lamaran</h2><?php foreach($lamaran['dokumenPersyaratan'] as $name=>$id):?><div class="document-row"><span class="activity-icon"><?= icon('file') ?></span><div><strong><?= e(documentOptions()[$name]??$name) ?></strong><small><?= e($dokumenInfo[(int)$id]['namaAsli']??'Dokumen PDF') ?></small></div><a class="button secondary" target="_blank" rel="noopener" href="<?= e(url('dokumen/lihat',['id'=>$id])) ?>">Lihat PDF ↗</a><a class="icon-button" aria-label="Unduh <?= e($name) ?>" href="<?= e(url('dokumen/lihat',['id'=>$id,'unduh'=>1])) ?>"><?= icon('download') ?></a></div><?php endforeach;?><?php if($lamaran['portofolio']):?><p><strong>Portofolio:</strong> <a target="_blank" rel="noopener noreferrer" href="<?= e($lamaran['portofolio']) ?>"><?= e($lamaran['portofolio']) ?> ↗</a></p><?php endif;?><h3>Surat Pengantar</h3><p class="prose"><?= nl2br(e($lamaran['suratPengantar']?:'Tidak ada surat pengantar tambahan.')) ?></p></section><section class="card"><h2>Riwayat Hasil Seleksi</h2><?php if(!$hasil):?><p class="muted">Menunggu peninjauan rekruter.</p><?php endif;?><?php foreach($hasil as $h):?><div class="history-item"><div class="section-heading"><strong><?= e($h['namaTahap']) ?></strong><?= badge($h['hasil']) ?></div><p><?= e($h['catatan']?:'Tidak ada catatan tambahan.') ?></p><small><?= tanggal($h['diperbaruiPada'],'d M Y, H:i') ?> WIB</small></div><?php endforeach;?></section></div>
<aside class="stack"><section class="card"><h2>Jadwal Seleksi</h2><?php if(!$jadwal):?><div class="empty-inline"><?= icon('calendar') ?><p>Belum ada jadwal dari rekruter.</p></div><?php endif;?><?php foreach($jadwal as $j):?><div class="agenda-detail"><span class="badge blue"><?= e($j['namaTahap']) ?></span><h3><?= e($j['judul']) ?></h3><p><?= tanggal($j['waktu'],'d M Y, H:i') ?> WIB</p><p><?= e($j['lokasi']) ?></p><p class="muted"><?= e($j['catatan']) ?></p><?php if($j['tautan']):?><a class="button secondary full" href="<?= e($j['tautan']) ?>" target="_blank" rel="noopener noreferrer">Buka tautan pertemuan ↗</a><?php endif;?></div><?php endforeach;?></section>
<?php if($currentUser['role']!=='Admin'):?><section class="card"><h3>Komunikasi seleksi</h3><?php if($lamaran['administrasiLolos']&&!$lamaran['perusahaanDihapus']):?><p class="muted">Koordinasikan tahap berikutnya melalui percakapan lamaran.</p><a class="button secondary full" href="<?= e(url('chat',['id'=>$lamaran['idLamaran']])) ?>"><?= icon('chat') ?> Buka Percakapan</a><?php else:?><p class="muted">Chat tersedia setelah lolos seleksi administrasi.</p><?php endif;?></section><?php endif;?>
<?php if($recruiter&&!in_array($lamaran['statusLamaran'],['Diterima','Ditolak','Draf'],true)&&!$lamaran['lowonganDihapus']):?><section class="card"><h2>Perbarui Hasil Seleksi</h2><p class="muted">Penilaian hanya untuk tahap aktif. Lolos memindahkan kandidat ke tahap berikutnya.</p><form method="post" action="<?= e(url('seleksi/status')) ?>"><?= csrf() ?><input type="hidden" name="idLamaran" value="<?= $lamaran['idLamaran'] ?>"><input type="hidden" name="idTahap" value="<?= $lamaran['idTahapSaatIni'] ?>"><label>Hasil Tahap Aktif<select name="hasil" required><option value="">Pilih hasil</option><option value="Diproses">Sedang diproses</option><option value="Lolos">Lolos tahap ini</option><option value="Tidak Lolos">Tidak lolos / tolak</option></select></label><label>Catatan<textarea name="catatan" rows="3" maxlength="2000" placeholder="Catatan akan terlihat oleh mahasiswa."></textarea></label><button class="button full">Simpan Hasil <?= icon('check') ?></button></form></section><section class="card"><h2>Atur Jadwal Seleksi</h2><form method="post" action="<?= e(url('seleksi/jadwal')) ?>"><?= csrf() ?><input type="hidden" name="idLamaran" value="<?= $lamaran['idLamaran'] ?>"><label>Tahap<select name="idTahap"><?php foreach($tahapan as $t):?><option value="<?= $t['idTahap'] ?>"<?= selected($lamaran['idTahapSaatIni'],$t['idTahap']) ?>><?= e($t['namaTahap']) ?></option><?php endforeach;?></select></label><label>Judul Jadwal<input name="judul" maxlength="150" required placeholder="Contoh: Wawancara bersama HR"></label><label>Tanggal &amp; Waktu (WIB)<input type="datetime-local" name="waktu" required></label><label>Lokasi<input name="lokasi" maxlength="150" placeholder="Online / alamat pertemuan"></label><label>Tautan Pertemuan<input type="url" name="tautan" maxlength="250" placeholder="https://…"></label><label>Catatan<textarea name="catatan" maxlength="2000" rows="2"></textarea></label><button class="button secondary full">Simpan Jadwal</button></form></section><?php endif;?></aside></div>
